test('createInvoice accepts discountPercent on lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 12.5 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
  assert.equal(r.value.lines[1].discountPercent, 12.5);
});

test('createInvoice defaults discountPercent to 0', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 0);
});

test('createInvoice returns DISCOUNT_INVALID for invalid discount', () => {
  const cases = [
    { discountPercent: -1, desc: 'negative' },
    { discountPercent: 101, desc: 'above 100' },
    { discountPercent: 'ten', desc: 'string' },
    { discountPercent: NaN, desc: 'NaN' },
    { discountPercent: Infinity, desc: 'Infinity' },
  ];
  for (const { discountPercent, desc } of cases) {
    assert.deepEqual(
      createInvoice({
        customerId: 'C-001',
        issueDate: '2026-10-07',
        lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent }],
      }),
      { ok: false, error: 'DISCOUNT_INVALID' },
      `should reject: ${desc}`
    );
  }
});

test('createInvoice accepts discount between 0 and 100', () => {
  const cases = [0, 0.01, 50, 99.99, 100];
  for (const discount of cases) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: discount }],
    });
    assert.equal(r.ok, true, `should accept: ${discount}`);
  }
});

test('addLine accepts discountPercent for new lines', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);

  const r = addLine(invoiceResult.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 15 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[1].discountPercent, 15);
});

test('addLine returns DISCOUNT_INVALID for invalid discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);

  assert.deepEqual(
    addLine(invoiceResult.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: -5 }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('addLine ignores discountPercent when increasing existing line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const r = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 5, discountPercent: 20 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].qty, 6);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('invoiceTotals returns discount and total structure', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const r = invoiceTotals(invoiceResult.value);
  assert.equal(r.ok, true);
  assert(r.value.hasOwnProperty('subtotal'));
  assert(r.value.hasOwnProperty('discount'));
  assert(r.value.hasOwnProperty('total'));
});

test('invoiceTotals calculates discount correctly', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 },
    ],
  });
  assert.equal(invoiceResult.ok, true);

  const r = invoiceTotals(invoiceResult.value);
  assert.equal(r.ok, true);
  const lineTotal1 = 10 * 9500; // 95000
  const lineTotal2 = 1 * 120000; // 120000
  const discount1 = Math.round(lineTotal1 * 10 / 100); // 9500
  const discount2 = Math.round(lineTotal2 * 20 / 100); // 24000
  assert.equal(r.value.subtotal, lineTotal1 + lineTotal2);
  assert.equal(r.value.discount, discount1 + discount2);
  assert.equal(r.value.total, r.value.subtotal - r.value.discount);
});

test('invoiceTotals with no discounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const r = invoiceTotals(invoiceResult.value);
  assert.equal(r.ok, true);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.total, r.value.subtotal);
});

test('invoiceTotals clamps total at 0 if discount exceeds subtotal', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ qty: 1, name: 'Test', unitPrice: 1000, vatRate: 21, discountPercent: 150 }],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.total, 0);
});

test('invoiceTotals with fractional discount rounding', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'ICON-SET', qty: 1, discountPercent: 33.33 }],
  });
  assert.equal(invoiceResult.ok, true);

  const r = invoiceTotals(invoiceResult.value);
  assert.equal(r.ok, true);
  const lineTotal = 1 * 980;
  const expectedDiscount = Math.round(lineTotal * 33.33 / 100 * 1e6) / 1e6;
  assert.equal(r.value.subtotal, lineTotal);
  assert(r.value.discount > 0);
});

