test('renderInvoiceText displays correct discounted total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 50 }],
  });
  assert.equal(invoiceResult.ok, true);

  const r = renderInvoiceText(invoiceResult.value);
  assert.equal(r.ok, true);
  const text = r.value;
  const lineTotal = 10 * 9500; // 95000 cents = €950.00
  const discount = lineTotal / 2; // 47500 cents = €475.00
  const total = lineTotal - discount; // 47500 cents = €475.00
  assert.match(text, /Total: €475\.00/);
});
